function walk(dir, acc = []) {
  for (const ENTRY of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, ENTRY.name)
    if (ENTRY.isDirectory()) {
      walk(full, acc)
    } else if (ENTRY.name.endsWith('.html') && ENTRY.name !== '404.html') {
      acc.push(full)
    }
  }
  return acc
}
